// CreateGoal is the resolver for the createGoal field.
func (r *mutationResolver) CreateGoal(ctx context.Context, input CreateGoalInput) (*BusinessGoal, error) {
	p, err := requireWorkspace(ctx, input.WorkspaceID, auth.PermOperate)
	if err != nil {
		return nil, err
	}
	title := strings.TrimSpace(input.Title)
	if title == "" || len(title) > 255 || len(input.Description) > 4000 {
		return nil, userErr("BAD_USER_INPUT", "title (1-255 chars) and description (max 4000 chars) are required")
	}
	if !input.TargetDeadline.After(time.Now()) {
		return nil, userErr("BAD_USER_INPUT", "targetDeadline must be in the future")
	}
	if r.AI == nil {
		return nil, userErr("UNAVAILABLE", "the AI planner is not configured")
	}

	constraints := map[string]string{}
	for k, v := range input.Constraints {
		constraints[k] = fmt.Sprint(v)
	}
	plan, err := r.AI.DecomposeGoal(ctx, p.WorkspaceID, "", title+"\n"+input.Description, constraints)
	if err != nil {
		return nil, userErr("UNAVAILABLE", "the AI planner could not produce a plan right now")
	}

	goal := repository.Goal{
		WorkspaceID: p.WorkspaceID, Title: title, Description: input.Description, TargetMetric: "custom",
		ProjectedMarginPct: decimal.NewFromFloat(plan.ProjectedMarginPct).Round(4),
		Deadline:           input.TargetDeadline, Status: "DRAFT",
	}
	goal.Constraints, _ = json.Marshal(input.Constraints)
	for _, m := range plan.Milestones {
		ms := repository.Milestone{StepOrder: m.StepOrder, Action: m.ToolAction, AssignedAgentRole: m.AssignedAgentRole}
		if m.CronSchedule != "" {
			c := m.CronSchedule
			ms.CronSchedule = &c
		}
		goal.Milestones = append(goal.Milestones, ms)
	}
	created, err := r.Repo.CreateGoal(ctx, goal)
	if err != nil {
		return nil, err
	}
	return goalToGQL(created), nil
}

// TriggerPlanExecution is the resolver for the triggerPlanExecution field.
func (r *mutationResolver) TriggerPlanExecution(ctx context.Context, goalID string) (*BusinessGoal, error) {
	p, err := auth.Require(ctx, auth.PermOperate)
	if err != nil {
		return nil, err
	}
	g, err := r.Repo.GetGoal(ctx, p.WorkspaceID, goalID)
	if err != nil {
		return nil, err
	}
	if g.Status != "DRAFT" && g.Status != "ACTIVE" {
		return nil, userErr("CONFLICT", "only draft or active goals can be executed")
	}
	for _, m := range g.Milestones {
		if m.IsCompleted {
			continue
		}
		payload, _ := json.Marshal(map[string]any{"goal_id": g.ID, "step_order": m.StepOrder, "assigned_agent_role": m.AssignedAgentRole})
		gid := g.ID
		// Deterministic key: triggering the plan twice never duplicates a milestone's ticket.
		if _, err := r.Tickets.Submit(ctx, ticketsSubmit(p.WorkspaceID, fmt.Sprintf("goal:%s:step:%d", g.ID, m.StepOrder), m.Action, payload, &gid)); err != nil {
			return nil, err
		}
	}
	if err := r.Repo.SetGoalStatus(ctx, p.WorkspaceID, g.ID, "ACTIVE"); err != nil {
		return nil, err
	}
	g, err = r.Repo.GetGoal(ctx, p.WorkspaceID, g.ID)
	if err != nil {
		return nil, err
	}
	return goalToGQL(g), nil
}

// CompileAndSavePolicy is the resolver for the compileAndSavePolicy field.
func (r *mutationResolver) CompileAndSavePolicy(ctx context.Context, input CompilePolicyInput) (*PolicyRule, error) {
	p, err := requireWorkspace(ctx, input.WorkspaceID, auth.PermAdmin)
	if err != nil {
		return nil, err
	}
	text := strings.TrimSpace(input.RawPolicyText)
	if text == "" || len(text) > 2000 {
		return nil, userErr("BAD_USER_INPUT", "policy text must be between 1 and 2000 characters")
	}
	if r.AI == nil {
		return nil, userErr("UNAVAILABLE", "the policy compiler is not configured")
	}
	res, err := r.AI.CompilePolicy(ctx, p.WorkspaceID, text)
	if err != nil {
		// The compiler rejects unsupported or ambiguous policies with a readable message.
		return nil, userErr("BAD_USER_INPUT", compilerMessage(err))
	}
	// The kernel is the authority on what it can enforce: validate before persisting.
	rules, err := kernel.ParseCompiledPolicy(res.CompiledAstJson)
	if err != nil {
		return nil, userErr("BAD_USER_INPUT", "the compiled policy is not enforceable: "+err.Error())
	}
	row, err := r.Repo.UpsertPolicyRule(ctx, repository.PolicyRuleRow{
		WorkspaceID: p.WorkspaceID, RuleKey: res.RuleId, TriggerEvent: res.TriggerEvent, RawPolicyText: text,
		CompiledAST: json.RawMessage(res.CompiledAstJson), AssignedApprovalRole: res.AssignedApprovalRole,
	})
	if err != nil {
		return nil, err
	}
	for _, rule := range rules {
		if err := r.Policy.AddRuleForWorkspace(p.WorkspaceID, rule); err != nil {
			return nil, err
		}
	}
	return &PolicyRule{ID: row.ID, TriggerEvent: row.TriggerEvent, CompiledAstJSON: jsonMap(row.CompiledAST), AssignedApprovalRole: row.AssignedApprovalRole}, nil
}

func compilerMessage(err error) string {
	msg := err.Error()
	if i := strings.Index(msg, "desc = "); i >= 0 {
		return msg[i+len("desc = "):]
	}
	return "the policy could not be compiled"
}

