// RegisterMCPConnection is the resolver for the registerMCPConnection field.
func (r *mutationResolver) RegisterMCPConnection(ctx context.Context, input RegisterMCPInput) (*MCPConnection, error) {
	p, err := requireWorkspace(ctx, input.WorkspaceID, auth.PermAdmin)
	if err != nil {
		return nil, err
	}
	if !serverNameRE.MatchString(input.ServerName) {
		return nil, userErr("BAD_USER_INPUT", "serverName must be lowercase letters, digits, '-' or '_' (2-64 chars, starting with a letter)")
	}
	if input.TransportType != "http" {
		return nil, userErr("BAD_USER_INPUT", "only the 'http' (Streamable HTTP) transport is supported; stdio servers cannot be run by a hosted backend")
	}
	if err := mcp.ValidateServerURI(input.ServerURI, r.AllowPrivateMCP); err != nil {
		return nil, userErr("BAD_USER_INPUT", err.Error())
	}
	if len(input.AllowedScopes) == 0 || len(input.AllowedScopes) > 100 {
		return nil, userErr("BAD_USER_INPUT", "allowedScopes must list between 1 and 100 tools (e.g. \"shopify.get_order\" or \"shopify.*\")")
	}
	for _, s := range input.AllowedScopes {
		if s == "" || len(s) > 128 {
			return nil, userErr("BAD_USER_INPUT", "each scope must be 1-128 characters")
		}
	}
	// Strict parse: unknown fields are rejected so typos cannot silently drop a credential.
	var creds mcp.Credentials
	dec := json.NewDecoder(strings.NewReader(input.RawCredentialsJSON))
	dec.DisallowUnknownFields()
	if err := dec.Decode(&creds); err != nil {
		return nil, userErr("BAD_USER_INPUT", `rawCredentialsJson must be JSON like {"bearer_token":"..."} or {"headers":{"X-Api-Key":"..."}}`)
	}
	if r.Vault == nil {
		return nil, userErr("UNAVAILABLE", "the credential vault is not configured")
	}
	enc, err := r.Vault.Encrypt(p.WorkspaceID, []byte(input.RawCredentialsJSON))
	if err != nil {
		return nil, err
	}
	scopes, _ := json.Marshal(input.AllowedScopes)
	c, err := r.Repo.CreateMCPConnection(ctx, repository.MCPConnection{
		WorkspaceID: p.WorkspaceID, ServerName: input.ServerName, TransportType: "http", ServerURI: input.ServerURI,
		EncryptedAuthRef: enc, AllowedScopes: scopes,
	})
	if err != nil {
		return nil, err
	}
	return mcpToGQL(*c), nil
}

