// ExecutionBoard is the resolver for the executionBoard field.
func (r *queryResolver) ExecutionBoard(ctx context.Context, workspaceID string) (*ExecutionBoardState, error) {
	if _, err := requireWorkspace(ctx, workspaceID, auth.PermRead); err != nil {
		return nil, err
	}
	counts, err := r.Repo.CountTicketsByStatus(ctx, workspaceID)
	if err != nil {
		return nil, err
	}
	recent, err := r.Repo.ListTickets(ctx, workspaceID, nil, 20, 0)
	if err != nil {
		return nil, err
	}
	conns, err := r.Repo.ListMCPConnections(ctx, workspaceID)
	if err != nil {
		return nil, err
	}
	health := HealthStatusHealthy
	for _, c := range conns {
		switch c.HealthStatus {
		case "CRITICAL":
			health = HealthStatusCritical
		case "DEGRADED":
			if health != HealthStatusCritical {
				health = HealthStatusDegraded
			}
		}
	}
	return &ExecutionBoardState{
		SystemHealth: health, IncomingCount: counts["QUEUED"], SyncingCount: counts["RUNNING"], ReconcilingCount: counts["COMPLETED"],
		PendingApprovalsCount: counts["PENDING_APPROVAL"] + counts["CONFLICT_HOLD"], RecentTickets: r.ticketsToGQL(ctx, recent),
	}, nil
}

