// pump forwards broker events of one topic to a typed channel until ctx ends.
func pump[T any](ctx context.Context, r *Resolver, topic string, convert func(any) (T, bool)) <-chan T {
	src, cancel := r.Broker.Subscribe(topic)
	out := make(chan T, 16)
	go func() {
		defer cancel()
		defer close(out)
		for {
			select {
			case <-ctx.Done():
				return
			case ev, ok := <-src:
				if !ok {
					return
				}
				v, ok := convert(ev)
				if !ok {
					continue
				}
				select {
				case out <- v:
				case <-ctx.Done():
					return
				}
			}
		}
	}()
	return out
}

